__ht__function(data, view) {
// 统一取值并转小写字符串标准化
let rolled = String(data.a('rolledState')).toLowerCase();
let running = String(data.a('runningState')).toLowerCase();

if ((rolled === '0' || rolled === 'false') && (running === '0' || running === 'false')) {
    return 'rgb(150,150,150)';
} else if ((rolled === '1' || rolled === 'true') && (running === '1' || running === 'true')) {
    return 'rgb(125,195,125)';  // 绿色
} else if ((rolled === '0' || rolled === 'false') && (running === '1' || running === 'true')) {
    return 'rgb(254,182,77)';  // 黄色
} else {
    return 'rgb(124,145,155)';  // 默认灰色
}
}
